return [
  {
    json: {
      name: 'KI & Tech',
      keywords: 'k%C3%BCnstliche+intelligenz+OR+AI+news+OR+machine+learning',
      webhook_url: 'DISCORD_WEBHOOK_KI_TECH',
      color: 5814783
    }
  },
  {
    json: {
      name: 'Linux & Open Source',
      keywords: 'Linux+open+source+news',
      webhook_url: 'DISCORD_WEBHOOK_LINUX',
      color: 3066993
    }
  },
  {
    json: {
      name: 'Gaming',
      keywords: 'gaming+news+videospiele',
      webhook_url: 'DISCORD_WEBHOOK_GAMING',
      color: 10181046
    }
  }
];

const xml = $input.item.json.data;

// Artikel per Regex extrahieren
const itemRegex = /<item>([\\s\\S]*?)<\/item>/g;
const titleRegex = /<title><![CDATA[([^\]]*?)\]\]><\/title>/;
const linkRegex = /<link>([^<]+)<\/link>/;
const pubDateRegex = /<pubDate>([^<]+)<\/pubDate>/;
const sourceRegex = /<source[^>]*>([^<]+)<\/source>/;

const items = [];
const seenUrls = new Set();
const now = Date.now();
const oneDayMs = 24 * 60 * 60 * 1000;

let match;
while ((match = itemRegex.exec(xml)) !== null) {
  const itemXml = match[1];

  const titleMatch = titleRegex.exec(itemXml);
  const linkMatch = linkRegex.exec(itemXml);
  const pubDateMatch = pubDateRegex.exec(itemXml);
  const sourceMatch = sourceRegex.exec(itemXml);

  if (!titleMatch || !linkMatch || !pubDateMatch) continue;

  const title = titleMatch[1].trim();
  const url = linkMatch[1].trim();
  const pubDate = new Date(pubDateMatch[1].trim());
  const source = sourceMatch ? sourceMatch[1].trim() : 'Unbekannt';

  // Nur Artikel der letzten 24h
  if (now - pubDate.getTime() > oneDayMs) continue;

  // Deduplizierung per URL
  if (seenUrls.has(url)) continue;
  seenUrls.add(url);

  items.push({
    title,
    url,
    source,
    published: pubDate.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' })
  });

  if (items.length >= 10) break;
}

const articlesText = items.map((a, i) =>
  `${i + 1}. ${a.title} (${a.source}, ${a.published})\n   URL: ${a.url}`
).join('\n\n');

return {
  json: {
    articles: articlesText,
    articlesList: items,
    count: items.length
  }
};

